function s(n){return`사용자 #${n.user_id}`}function i(n){let e=(n.name??"").trim();return e===""?s(n):e}function u(n,e){let r=i(n);return e.some(t=>t.user_id!==n.user_id&&i(t)===r)}function o(n,e){let r=i(n);if(!u(n,e))return r;let t=(n.github_login??"").trim();return t===""?`${r} · GitHub 미연결`:`${r} · @${t}`}function f(n,e){if(!u(n,e))return!0;let r=o(n,e);return!e.some(t=>t.user_id!==n.user_id&&o(t,e)===r)}function a(){return"이름이 같은 팀원이 있습니다 — GitHub 아이디를 연결하면 구분됩니다"}export{o as a,f as b,a as c};
